import { test, expect } from '@playwright/test';

test.describe('Page Title Update on Section Navigation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/');
  });

  test('should update page title when navigating between sections', async ({ page }) => {
    // Verify initial page title
    await expect(page).toHaveTitle('Home');

    // Click on 'About' section link
    const aboutLink = page.getByRole('link', { name: 'About' });
    await aboutLink.click();

    // Verify page title updates to 'About Us'
    await expect(page).toHaveTitle('About Us');

    // Click on 'Contact' section link
    const contactLink = page.getByRole('link', { name: 'Contact' });
    await contactLink.click();

    // Verify page title updates to 'Contact Us'
    await expect(page).toHaveTitle('Contact Us');

    // Click on 'Home' section link again
    await aboutLink.click();
    await contactLink.click();
    await aboutLink.click();
    await contactLink.click();
    await aboutLink.click();

    // Verify page title returns to 'Home'
    await expect(page).toHaveTitle('Home');
  });

  test('should handle navigation to non-existent section gracefully', async ({ page }) => {
    // Verify initial page title
    await expect(page).toHaveTitle('Home');

    // Attempt to navigate to a non-existent section
    const invalidLink = page.getByRole('link', { name: 'Invalid Section' });

    // Verify invalid link does not exist
    const linkExists = await invalidLink.isVisible();
    expect(linkExists).toBe(false);

    // Verify page title remains unchanged
    await expect(page).toHaveTitle('Home');

    // Verify error message is not displayed
    const errorMessage = page.getByText('Section not found');
    const isErrorVisible = await errorMessage.isVisible();
    expect(isErrorVisible).toBe(false);

    // Navigate to a valid section
    const aboutLink = page.getByRole('link', { name: 'About' });
    await aboutLink.click();

    // Verify page title updates to 'About Us'
    await expect(page).toHaveTitle('About Us');
  });
});
